-- Touchline — 0016: "Cups & careers" (phase 4b): the league cup (knockout bracket), youth academy prospects,
-- contract renewals and free agents (Bosman). Additive. Ties, prospects and contract demands are generated by the
-- server; user commands only act on stored rows.

-- ------------------------------------------------------------------ cup
create table if not exists public.cup_ties (
  id               uuid primary key default gen_random_uuid(),
  game_id          uuid not null references public.games(id) on delete cascade,
  season           integer not null,
  round            integer not null check (round >= 1),
  slot             integer not null check (slot >= 1),
  home_club_id     uuid references public.game_clubs(id) on delete set null,
  away_club_id     uuid references public.game_clubs(id) on delete set null,
  after_league_round integer not null,
  status           text not null default 'scheduled' check (status in ('scheduled','bye','played')),
  home_goals       smallint,
  away_goals       smallint,
  pens_home        smallint,
  pens_away        smallint,
  winner_club_id   uuid references public.game_clubs(id) on delete set null,
  result_json      jsonb,
  played_at        timestamptz,
  unique (game_id, season, round, slot)
);
create index if not exists cup_ties_game_idx on public.cup_ties(game_id, season, round);

-- ------------------------------------------------------------------ academy
create table if not exists public.academy_prospects (
  id              uuid primary key default gen_random_uuid(),
  game_id         uuid not null references public.games(id) on delete cascade,
  club_id         uuid not null references public.game_clubs(id) on delete cascade,
  season          integer not null,
  name            text not null,
  position_group  text not null check (position_group in ('GK','DEF','MID','ATT')),
  age             smallint not null check (age between 15 and 21),
  ovr             smallint not null check (ovr between 30 and 80),
  potential_cap   smallint not null check (potential_cap between 30 and 99),
  potential_band  text not null,
  dev_rate        numeric(4,3) not null default 1.0,
  wage_cents      bigint not null check (wage_cents >= 0),
  value_cents     bigint not null check (value_cents >= 0),
  status          text not null default 'academy' check (status in ('academy','promoted','released')),
  player_id       uuid references public.game_players(id) on delete set null,
  created_at      timestamptz not null default now(),
  decided_at      timestamptz,
  unique (club_id, season, name)
);

-- ------------------------------------------------------------------ contracts
alter table public.game_players add column if not exists free_agent_since integer;
alter table public.game_players add column if not exists free_agent_wage_cents bigint;
create index if not exists game_players_free_agents on public.game_players(game_id) where club_id is null and free_agent_since is not null;
-- game_players uses column-level grants (potential is hidden): expose the new public columns
grant select (free_agent_since, free_agent_wage_cents) on public.game_players to authenticated;

create table if not exists public.contract_talks (
  id          uuid primary key default gen_random_uuid(),
  game_id     uuid not null references public.games(id) on delete cascade,
  club_id     uuid not null references public.game_clubs(id) on delete cascade,
  player_id   uuid not null references public.game_players(id) on delete cascade,
  season      integer not null,
  refuses     boolean not null default false,
  options     jsonb not null,             -- [{seasons, wage_cents}]
  status      text not null default 'open' check (status in ('open','renewed','left','void')),
  chosen      jsonb,
  created_at  timestamptz not null default now(),
  decided_at  timestamptz,
  unique (player_id, season)
);

do $$
declare t text;
begin
  foreach t in array array['cup_ties','academy_prospects','contract_talks'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon, authenticated', t);
    execute format('grant select on public.%I to authenticated', t);
  end loop;
end $$;
create policy member_read on public.cup_ties for select to authenticated using (public.is_game_member(game_id));
create policy own_club_read on public.academy_prospects for select to authenticated using (public.manages_club(club_id));
create policy own_club_read on public.contract_talks for select to authenticated using (public.manages_club(club_id));

-- ------------------------------------------------------------------ user commands
create or replace function public.promote_prospect(p_prospect_id uuid) returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_x public.academy_prospects; v_game public.games; v_club uuid; v_count int; v_id uuid;
begin
  select * into v_x from public.academy_prospects where id = p_prospect_id for update;
  if not found or not public.manages_club(v_x.club_id) then perform public._fail('not_found', 'Jovem inexistente.'); end if;
  v_club := public._my_active_club(v_x.game_id);
  if v_x.status <> 'academy' then perform public._fail('decided', 'Este jovem já não está na academia.'); end if;
  select * into v_game from public.games where id = v_x.game_id;
  select count(*) into v_count from public.game_players where club_id = v_club;
  if v_count + 1 > public._setting_int(v_game, 'max_squad', 32) then perform public._fail('squad_max', 'O plantel está cheio.'); end if;
  insert into public.game_players (game_id, source_player_id, club_id, name_snapshot, position_group, position_detail,
    birth_date, age_known, age, initial_ovr, season_start_ovr, current_ovr, potential_cap, hidden_development_rate,
    profile_json, morale, fitness, sharpness, market_value_cents, wage_cents, contract_end_season)
  values (v_x.game_id, null, v_club, v_x.name, v_x.position_group, null, null, true, v_x.age, v_x.ovr, v_x.ovr, v_x.ovr,
          v_x.potential_cap, v_x.dev_rate, jsonb_build_object('academy', true), 70, 100, 50, v_x.value_cents, v_x.wage_cents,
          v_game.current_season + 3)
  returning id into v_id;
  update public.academy_prospects set status = 'promoted', player_id = v_id, decided_at = now() where id = v_x.id;
  perform public._audit(v_x.game_id, auth.uid(), 'academy.promote', 'academy_prospect', v_x.id::text, jsonb_build_object('player_id', v_id));
  return v_id;
end $$;

create or replace function public.release_prospect(p_prospect_id uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_x public.academy_prospects;
begin
  select * into v_x from public.academy_prospects where id = p_prospect_id for update;
  if not found or not public.manages_club(v_x.club_id) then perform public._fail('not_found', 'Jovem inexistente.'); end if;
  perform public._my_active_club(v_x.game_id);
  if v_x.status <> 'academy' then perform public._fail('decided', 'Este jovem já não está na academia.'); end if;
  update public.academy_prospects set status = 'released', decided_at = now() where id = v_x.id;
end $$;

create or replace function public.renew_contract(p_talk_id uuid, p_seasons integer) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_t public.contract_talks; v_game public.games; v_opt jsonb;
begin
  select * into v_t from public.contract_talks where id = p_talk_id for update;
  if not found or not public.manages_club(v_t.club_id) then perform public._fail('not_found', 'Negociação inexistente.'); end if;
  perform public._my_active_club(v_t.game_id);
  select * into v_game from public.games where id = v_t.game_id;
  if v_t.status <> 'open' or v_t.season <> v_game.current_season then perform public._fail('closed', 'Esta negociação já terminou.'); end if;
  if v_t.refuses then perform public._fail('refuses', 'O jogador não quer renovar.'); end if;
  if not exists (select 1 from public.game_players where id = v_t.player_id and club_id = v_t.club_id) then perform public._fail('player_moved', 'O jogador já não é teu.'); end if;
  select o into v_opt from jsonb_array_elements(v_t.options) o where (o->>'seasons')::int = p_seasons;
  if v_opt is null then perform public._fail('invalid', 'Duração inválida.'); end if;
  update public.game_players set contract_end_season = v_game.current_season + p_seasons, wage_cents = (v_opt->>'wage_cents')::bigint,
         morale = least(100, morale + 3), version = version + 1, updated_at = now()
   where id = v_t.player_id;
  update public.contract_talks set status = 'renewed', chosen = v_opt, decided_at = now() where id = v_t.id;
  perform public._audit(v_t.game_id, auth.uid(), 'contract.renew', 'game_player', v_t.player_id::text, v_opt);
  return v_opt;
end $$;

-- free agents can be signed (no fee, the stored wage) during the first 3 rounds of a season
create or replace function public.sign_free_agent(p_player_id uuid) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_p public.game_players; v_game public.games; v_club uuid; v_count int;
begin
  select * into v_p from public.game_players where id = p_player_id for update;
  if not found or not public.is_game_member(v_p.game_id) then perform public._fail('not_found', 'Jogador inexistente.'); end if;
  v_club := public._my_active_club(v_p.game_id);
  if v_p.club_id is not null or v_p.free_agent_since is null then perform public._fail('not_free', 'Este jogador não está livre.'); end if;
  select * into v_game from public.games where id = v_p.game_id;
  if v_game.current_matchday > 3 then perform public._fail('window_closed', 'O mercado de jogadores livres fecha à 3.ª jornada.'); end if;
  select count(*) into v_count from public.game_players where club_id = v_club;
  if v_count + 1 > public._setting_int(v_game, 'max_squad', 32) then perform public._fail('squad_max', 'O plantel está cheio.'); end if;
  update public.game_players set club_id = v_club, wage_cents = coalesce(free_agent_wage_cents, wage_cents),
         contract_end_season = v_game.current_season + 2, free_agent_since = null, free_agent_wage_cents = null,
         morale = 70, version = version + 1, updated_at = now()
   where id = v_p.id;
  insert into public.transfer_transactions (game_id, player_id, from_club_id, to_club_id, price_cents, offer_id, season_number)
  values (v_p.game_id, v_p.id, null, v_club, 0, null, v_game.current_season);
  perform public._audit(v_p.game_id, auth.uid(), 'free_agent.sign', 'game_player', v_p.id::text);
  return jsonb_build_object('player_id', v_p.id);
end $$;

do $$
declare f text;
begin
  foreach f in array array['promote_prospect(uuid)', 'release_prospect(uuid)', 'renew_contract(uuid, integer)', 'sign_free_agent(uuid)'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated, service_role', f);
  end loop;
end $$;
